import sys
import re

INT = re.compile(r'-?[0-9]+\Z')


def evaluate(line):
    st = []
    for t in line.split():
        if t in ('+', '-', '*', '/'):
            if len(st) < 2:
                return 'error: underflow'
            b = st.pop()
            a = st.pop()
            if t == '+':
                st.append(a + b)
            elif t == '-':
                st.append(a - b)
            elif t == '*':
                st.append(a * b)
            else:
                if b == 0:
                    return 'error: divzero'
                q = abs(a) // abs(b)
                st.append(q if (a < 0) == (b < 0) else -q)
        elif INT.match(t):
            st.append(int(t))
        else:
            return 'error: token'
    if len(st) != 1:
        return 'error: leftover'
    return str(st[0])


out = []
for line in sys.stdin.read().split('\n'):
    if line.strip() == '':
        continue
    out.append(evaluate(line))
if out:
    print('\n'.join(out))
